content.content:
"""The ``stockroom`` command line."""

import csv
import io
import json
import os
import re
import sys

from . import orders as ordmod
from . import shelves
from .parsing import (
    Movement, ParseError, first_below_zero, normalise_order_id, normalise_sku,
    parse_catalog, parse_date, parse_movements, parse_orders,
)

USAGE = (
    "usage: stockroom [--dir DIR] stock|low [--json] | history SKU [--json] | "
    "receive|ship DATE SKU QUANTITY [NOTE] | quote|invoice ORDER [--json] | "
    "fulfil ORDER DATE | report [--format text|csv|json]"
)

CATALOG, MOVEMENTS, ORDERS = "catalog", "movements", "orders"
JSON_OPT, FORMAT_OPT, DIR_OPT = "--json", "--format", "--dir"

# command -> (positional counts, option it takes, files it reads)
COMMANDS = {
    "stock": ((0,), JSON_OPT, (CATALOG, MOVEMENTS)),
    "low": ((0,), JSON_OPT, (CATALOG, MOVEMENTS)),
    "history": ((1,), JSON_OPT, (CATALOG, MOVEMENTS)),
    "receive": ((3, 4), None, (CATALOG, MOVEMENTS)),
    "ship": ((3, 4), None, (CATALOG, MOVEMENTS)),
    "quote": ((1,), JSON_OPT, (CATALOG, ORDERS)),
    "fulfil": ((2,), None, (CATALOG, MOVEMENTS, ORDERS)),
    "invoice": ((1,), JSON_OPT, (CATALOG, MOVEMENTS, ORDERS)),
    "report": ((0,), FORMAT_OPT, (CATALOG, MOVEMENTS, ORDERS)),
}
MUTATING = ("receive", "ship", "fulfil")
_UINT = re.compile(r"[0-9]+")


class UsageError(Exception):
    """Something wrong with the command line (exit 2)."""


class Failure(Exception):
    """A file mistake or refusal (exit 1) or unreadable file (exit 2)."""

    def __init__(self, code, message):
        super().__init__(message)
        self.code = code


def refuse(message):
    return Failure(1, message)


# ---------------------------------------------------------------- arguments

def _find_command(argv):
    index = 0
    while index < len(argv):
        arg = argv[index]
        if arg in (DIR_OPT, FORMAT_OPT):
            index += 2
        elif arg.startswith("-") and arg != "-":
            index += 1
        else:
            return index
    return None


def parse_args(argv):
    """Return (command, positionals, options); raise UsageError."""
    at = _find_command(argv)
    if at is None:
        raise UsageError("missing command")
    command = argv[at]
    if command not in COMMANDS:
        raise UsageError("unknown command %r" % command)
    counts, extra_opt, _ = COMMANDS[command]
    options, positionals = {}, []

    def setopt(name, value):
        if name in options:
            raise UsageError("option %s given more than once" % name)
        options[name] = value

    index = 0
    while index < len(argv):
        arg = argv[index]
        if index == at:
            index += 1
            continue
        name = value = None
        if arg == DIR_OPT or (extra_opt == FORMAT_OPT and arg == FORMAT_OPT):
            if index + 1 >= len(argv):
                raise UsageError("option %s needs a value" % arg)
            name, value = arg, argv[index + 1]
            index += 1
        elif arg.startswith(DIR_OPT + "="):
            name, value = DIR_OPT, arg[len(DIR_OPT) + 1:]
        elif extra_opt == FORMAT_OPT and arg.startswith(FORMAT_OPT + "="):
            name, value = FORMAT_OPT, arg[len(FORMAT_OPT) + 1:]
        elif extra_opt == JSON_OPT and arg == JSON_OPT:
            name, value = JSON_OPT, True
        elif command not in MUTATING and arg.startswith("-") and arg != "-":
            raise UsageError("unknown option %s" % arg)
        index += 1
        if name is None:
            positionals.append(arg)
        else:
            if name == FORMAT_OPT and value not in ("text", "csv", "json"):
                raise UsageError("bad --format value %r" % value)
            setopt(name, value)
    if len(positionals) not in counts:
        raise UsageError("wrong number of arguments for %s" % command)
    date_arg = {"receive": 0, "ship": 0, "fulfil": 1}.get(command)
    if date_arg is not None and parse_date(positionals[date_arg]) is None:
        raise UsageError("bad date %r (want YYYY-MM-DD)" % positionals[date_arg])
    return command, positionals, options


# -------------------------------------------------------------------- files

def _read(directory, kind):
    name = kind + ".txt"
    try:
        with open(os.path.join(directory, name), "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if kind == CATALOG:
            raise Failure(2, "%s: no such file" % name)
        return name, b""
    except OSError as exc:
        raise Failure(2, "%s: %s" % (name, exc.strerror or exc))
    return name, data


def _decode(name, data):
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise Failure(2, "%s: not valid UTF-8" % name)


def _parse(name, func, *args):
    try:
        return func(*args)
    except ParseError as exc:
        raise Failure(1, "%s: %s" % (name, exc))


def _append(directory, existing, lines):
    path = os.path.join(directory, MOVEMENTS + ".txt")
    data = "".join(line + "\n" for line in lines).encode("utf-8")
    if existing and not existing.endswith(b"\n"):
        data = b"\n" + data
    try:
        with open(path, "ab") as handle:
            handle.write(data)
    except OSError as exc:
        raise Failure(2, "%s.txt: %s" % (MOVEMENTS, exc.strerror or exc))


# ------------------------------------------------------------------ outputs

def _lines(rows):
    return "".join(row + "\n" for row in rows)


def _json(obj):
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def _csv(rows):
    buffer = io.StringIO()
    csv.writer(buffer, lineterminator="\n").writerows(rows)
    return buffer.getvalue()


def _quote_output(quote, as_json, prefix=""):
    if as_json:
        return _json({
            "order": quote.order,
            "date": quote.date.isoformat(),
            "customer": quote.customer,
            "lines": [
                {"sku": l.sku, "quantity": l.quantity, "unit": str(l.unit),
                 "gross": str(l.gross), "discount": str(l.discount), "net": str(l.net)}
                for l in quote.lines
            ],
            "subtotal": str(quote.subtotal),
            "order_discount": str(quote.order_discount),
            "tax": str(quote.tax),
            "total": str(quote.total),
        })
    rows = ["%s%s %s %s" % (prefix, quote.order, quote.date.isoformat(), quote.customer)]
    rows += ["%s %d %s %s %s %s" % (l.sku, l.quantity, l.unit, l.gross, l.discount, l.net)
             for l in quote.lines]
    rows += ["subtotal %s" % quote.subtotal, "order discount %s" % quote.order_discount,
             "tax %s" % quote.tax, "total %s" % quote.total]
    return _lines(rows)


# ----------------------------------------------------------------- commands

def _cmd_stock(catalog, moves, as_json):
    rows = shelves.stock_rows(catalog, moves)
    if as_json:
        return _json([{"sku": p.sku, "name": p.name, "onhand": n, "status": s}
                      for p, n, s in rows])
    return _lines("%s %d %s %s" % (p.sku, n, s, p.name) for p, n, s in rows)


def _cmd_low(catalog, moves, as_json):
    rows = shelves.low_rows(catalog, moves)
    if as_json:
        return _json([{"sku": p.sku, "onhand": n, "reorder": p.reorder, "buy": b}
                      for p, n, b in rows])
    return _lines("%s %d %d %d" % (p.sku, n, p.reorder, b) for p, n, b in rows)


def _cmd_history(catalog, moves, as_json, arg):
    sku = normalise_sku(arg)
    if sku is None or sku not in catalog:
        raise refuse("unknown SKU %r" % arg)
    rows = shelves.history_rows(sku, moves)
    if as_json:
        return _json([{"date": m.date.isoformat(), "delta": "%+d" % m.quantity,
                       "balance": b, "note": m.note} for m, b in rows])
    return _lines(
        "%s %+d %d%s" % (m.date.isoformat(), m.quantity, b, " " + m.note if m.note else "")
        for m, b in rows
    )


def _cmd_move(command, catalog, moves, existing, directory, args):
    date_text, sku_arg, qty_arg = args[:3]
    note = args[3].strip(" \t") if len(args) == 4 else ""
    if not _UINT.fullmatch(qty_arg) or int(qty_arg) < 1:
        raise refuse("quantity must be a whole number of one or more, got %r" % qty_arg)
    sku = normalise_sku(sku_arg)
    if sku is None or sku not in catalog:
        raise refuse("unknown SKU %r" % sku_arg)
    if "\n" in note or "\r" in note:
        raise refuse("a note may not contain a line break")
    try:
        note.encode("utf-8")
    except UnicodeEncodeError:
        raise refuse("note is not valid text")
    quantity = int(qty_arg) * (1 if command == "receive" else -1)
    new = Movement(parse_date(date_text), sku, quantity, note)
    _check_and_append(directory, moves, existing, [new])
    return shelves.format_movement(new) + "\n"


def _check_and_append(directory, moves, existing, new_moves):
    found = first_below_zero(list(moves) + new_moves)
    if found:
        move, total = found
        if move in new_moves and move.line == 0:
            raise refuse("stock of %s would go below zero (%d)" % (move.sku, total))
        raise refuse("%s.txt: line %d: stock of %s would go below zero (%d)"
                     % (MOVEMENTS, move.line, move.sku, total))
    _append(directory, existing, [shelves.format_movement(m) for m in new_moves])


def _find_order(orders, arg):
    order_id = normalise_order_id(arg)
    for order in orders:
        if order.id == order_id:
            return order
    raise refuse("unknown order %r" % arg)


def _cmd_fulfil(catalog, moves, orders, existing, directory, args):
    order = _find_order(orders, args[0])
    date = parse_date(args[1])
    if date < order.date:
        raise refuse("cannot ship %s on %s: before the order date %s"
                     % (order.id, date.isoformat(), order.date.isoformat()))
    report, new_moves = ordmod.plan_fulfil(order, moves, date)
    if new_moves:
        _check_and_append(directory, moves, existing, new_moves)
    shipped = ordmod.shipped_so_far(order, list(moves) + new_moves)
    rows = ["%s shipped %d backordered %d" % row for row in report]
    rows.append("status " + ordmod.order_status(order, shipped))
    return _lines(rows)


def _cmd_invoice(catalog, moves, orders, as_json, arg):
    order = _find_order(orders, arg)
    shipped = ordmod.shipped_so_far(order, moves)
    if not any(shipped.values()):
        raise refuse("nothing has shipped for %s" % order.id)
    quote = ordmod.price_order(ordmod.invoice_order(order, shipped), catalog)
    return _quote_output(quote, as_json, "invoice ")


def _cmd_report(catalog, moves, orders, fmt):
    rows = []
    for order in sorted(orders, key=lambda o: (o.date, int(o.id[3:]), o.id)):
        shipped = ordmod.shipped_so_far(order, moves)
        units = sum(shipped.values())
        quoted = ordmod.price_order(order, catalog).total
        invoiced = ordmod.money(0)
        if units:
            invoiced = ordmod.price_order(ordmod.invoice_order(order, shipped), catalog).total
        rows.append((order.id, order.date.isoformat(), order.customer,
                     ordmod.order_status(order, shipped),
                     sum(q for _, q in order.lines), units, str(quoted), str(invoiced)))
    if fmt == "json":
        keys = ("order", "date", "customer", "status", "ordered", "shipped",
                "quoted", "invoiced")
        return _json([dict(zip(keys, row)) for row in rows])
    if fmt == "csv":
        return _csv([("order", "date", "customer", "status", "ordered", "shipped",
                      "quoted", "invoiced")] + rows)
    return _lines("%s %s %s %s %d/%d %s %s" % (r[:4] + (r[5], r[4], r[6], r[7]))
                  for r in rows)


def run(argv):
    """Carry out one command line; return the stdout text or raise."""
    command, args, options = parse_args(argv)
    directory = options.get(DIR_OPT, ".")
    if not os.path.isdir(directory):
        raise Failure(2, "%s: not a directory" % directory)
    raw = {kind: _read(directory, kind) for kind in COMMANDS[command][2]}
    text = {kind: _decode(*raw[kind]) for kind in raw}
    catalog = _parse("catalog.txt", parse_catalog, text[CATALOG])
    moves = orders = None
    if MOVEMENTS in text:
        moves = _parse("movements.txt", parse_movements, text[MOVEMENTS], catalog)
    if ORDERS in text:
        orders = _parse("orders.txt", parse_orders, text[ORDERS], catalog)
    as_json = bool(options.get(JSON_OPT))
    existing = raw[MOVEMENTS][1] if MOVEMENTS in raw else b""
    if command == "stock":
        return _cmd_stock(catalog, moves, as_json)
    if command == "low":
        return _cmd_low(catalog, moves, as_json)
    if command == "history":
        return _cmd_history(catalog, moves, as_json, args[0])
    if command in ("receive", "ship"):
        return _cmd_move(command, catalog, moves, existing, directory, args)
    if command == "quote":
        order = _find_order(orders, args[0])
        return _quote_output(ordmod.price_order(order, catalog), as_json)
    if command == "fulfil":
        return _cmd_fulfil(catalog, moves, orders, existing, directory, args)
    if command == "invoice":
        return _cmd_invoice(catalog, moves, orders, as_json, args[0])
    return _cmd_report(catalog, moves, orders, options.get(FORMAT_OPT, "text"))


def _silence_stdout():
    """Point fd 1 at /dev/null so the exit-time flush cannot fail again."""
    try:
        fd = os.open(os.devnull, os.O_WRONLY)
        os.dup2(fd, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def _emit(text):
    try:
        sys.stdout.write(text)
        sys.stdout.flush()
    except BrokenPipeError:
        _silence_stdout()
    except OSError as exc:
        _silence_stdout()
        sys.stderr.write("stockroom: cannot write output: %s\n" % (exc.strerror or exc))
        return 2
    return 0


def _configure_streams():
    for stream, options in ((sys.stdout, {"encoding": "utf-8", "newline": "\n"}),
                            (sys.stderr, {"errors": "backslashreplace"})):
        reconfigure = getattr(stream, "reconfigure", None)
        if reconfigure is not None:
            try:
                reconfigure(**options)
            except (OSError, ValueError):
                pass


def main(argv=None):
    """Entry point: run the command line and return the exit status."""
    argv = sys.argv[1:] if argv is None else list(argv)
    _configure_streams()
    try:
        text = run(argv)
    except UsageError as exc:
        sys.stderr.write("stockroom: %s\n%s\n" % (exc, USAGE))
        return 2
    except Failure as exc:
        sys.stderr.write("stockroom: %s\n" % exc)
        return exc.code
    return _emit(text)

toolUseResult.stdout:
"""The ``stockroom`` command line."""

import csv
import io
import json
import os
import re
import sys

from . import orders as ordmod
from . import shelves
from .parsing import (
    Movement, ParseError, first_below_zero, normalise_order_id, normalise_sku,
    parse_catalog, parse_date, parse_movements, parse_orders,
)

USAGE = (
    "usage: stockroom [--dir DIR] stock|low [--json] | history SKU [--json] | "
    "receive|ship DATE SKU QUANTITY [NOTE] | quote|invoice ORDER [--json] | "
    "fulfil ORDER DATE | report [--format text|csv|json]"
)

CATALOG, MOVEMENTS, ORDERS = "catalog", "movements", "orders"
JSON_OPT, FORMAT_OPT, DIR_OPT = "--json", "--format", "--dir"

# command -> (positional counts, option it takes, files it reads)
COMMANDS = {
    "stock": ((0,), JSON_OPT, (CATALOG, MOVEMENTS)),
    "low": ((0,), JSON_OPT, (CATALOG, MOVEMENTS)),
    "history": ((1,), JSON_OPT, (CATALOG, MOVEMENTS)),
    "receive": ((3, 4), None, (CATALOG, MOVEMENTS)),
    "ship": ((3, 4), None, (CATALOG, MOVEMENTS)),
    "quote": ((1,), JSON_OPT, (CATALOG, ORDERS)),
    "fulfil": ((2,), None, (CATALOG, MOVEMENTS, ORDERS)),
    "invoice": ((1,), JSON_OPT, (CATALOG, MOVEMENTS, ORDERS)),
    "report": ((0,), FORMAT_OPT, (CATALOG, MOVEMENTS, ORDERS)),
}
MUTATING = ("receive", "ship", "fulfil")
_UINT = re.compile(r"[0-9]+")


class UsageError(Exception):
    """Something wrong with the command line (exit 2)."""


class Failure(Exception):
    """A file mistake or refusal (exit 1) or unreadable file (exit 2)."""

    def __init__(self, code, message):
        super().__init__(message)
        self.code = code


def refuse(message):
    return Failure(1, message)


# ---------------------------------------------------------------- arguments

def _find_command(argv):
    index = 0
    while index < len(argv):
        arg = argv[index]
        if arg in (DIR_OPT, FORMAT_OPT):
            index += 2
        elif arg.startswith("-") and arg != "-":
            index += 1
        else:
            return index
    return None


def parse_args(argv):
    """Return (command, positionals, options); raise UsageError."""
    at = _find_command(argv)
    if at is None:
        raise UsageError("missing command")
    command = argv[at]
    if command not in COMMANDS:
        raise UsageError("unknown command %r" % command)
    counts, extra_opt, _ = COMMANDS[command]
    options, positionals = {}, []

    def setopt(name, value):
        if name in options:
            raise UsageError("option %s given more than once" % name)
        options[name] = value

    index = 0
    while index < len(argv):
        arg = argv[index]
        if index == at:
            index += 1
            continue
        name = value = None
        if arg == DIR_OPT or (extra_opt == FORMAT_OPT and arg == FORMAT_OPT):
            if index + 1 >= len(argv):
                raise UsageError("option %s needs a value" % arg)
            name, value = arg, argv[index + 1]
            index += 1
        elif arg.startswith(DIR_OPT + "="):
            name, value = DIR_OPT, arg[len(DIR_OPT) + 1:]
        elif extra_opt == FORMAT_OPT and arg.startswith(FORMAT_OPT + "="):
            name, value = FORMAT_OPT, arg[len(FORMAT_OPT) + 1:]
        elif extra_opt == JSON_OPT and arg == JSON_OPT:
            name, value = JSON_OPT, True
        elif command not in MUTATING and arg.startswith("-") and arg != "-":
            raise UsageError("unknown option %s" % arg)
        index += 1
        if name is None:
            positionals.append(arg)
        else:
            if name == FORMAT_OPT and value not in ("text", "csv", "json"):
                raise UsageError("bad --format value %r" % value)
            setopt(name, value)
    if len(positionals) not in counts:
        raise UsageError("wrong number of arguments for %s" % command)
    date_arg = {"receive": 0, "ship": 0, "fulfil": 1}.get(command)
    if date_arg is not None and parse_date(positionals[date_arg]) is None:
        raise UsageError("bad date %r (want YYYY-MM-DD)" % positionals[date_arg])
    return command, positionals, options


# -------------------------------------------------------------------- files

def _read(directory, kind):
    name = kind + ".txt"
    try:
        with open(os.path.join(directory, name), "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if kind == CATALOG:
            raise Failure(2, "%s: no such file" % name)
        return name, b""
    except OSError as exc:
        raise Failure(2, "%s: %s" % (name, exc.strerror or exc))
    return name, data


def _decode(name, data):
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise Failure(2, "%s: not valid UTF-8" % name)


def _parse(name, func, *args):
    try:
        return func(*args)
    except ParseError as exc:
        raise Failure(1, "%s: %s" % (name, exc))


def _append(directory, existing, lines):
    path = os.path.join(directory, MOVEMENTS + ".txt")
    data = "".join(line + "\n" for line in lines).encode("utf-8")
    if existing and not existing.endswith(b"\n"):
        data = b"\n" + data
    try:
        with open(path, "ab") as handle:
            handle.write(data)
    except OSError as exc:
        raise Failure(2, "%s.txt: %s" % (MOVEMENTS, exc.strerror or exc))


# ------------------------------------------------------------------ outputs

def _lines(rows):
    return "".join(row + "\n" for row in rows)


def _json(obj):
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def _csv(rows):
    buffer = io.StringIO()
    csv.writer(buffer, lineterminator="\n").writerows(rows)
    return buffer.getvalue()


def _quote_output(quote, as_json, prefix=""):
    if as_json:
        return _json({
            "order": quote.order,
            "date": quote.date.isoformat(),
            "customer": quote.customer,
            "lines": [
                {"sku": l.sku, "quantity": l.quantity, "unit": str(l.unit),
                 "gross": str(l.gross), "discount": str(l.discount), "net": str(l.net)}
                for l in quote.lines
            ],
            "subtotal": str(quote.subtotal),
            "order_discount": str(quote.order_discount),
            "tax": str(quote.tax),
            "total": str(quote.total),
        })
    rows = ["%s%s %s %s" % (prefix, quote.order, quote.date.isoformat(), quote.customer)]
    rows += ["%s %d %s %s %s %s" % (l.sku, l.quantity, l.unit, l.gross, l.discount, l.net)
             for l in quote.lines]
    rows += ["subtotal %s" % quote.subtotal, "order discount %s" % quote.order_discount,
             "tax %s" % quote.tax, "total %s" % quote.total]
    return _lines(rows)


# ----------------------------------------------------------------- commands

def _cmd_stock(catalog, moves, as_json):
    rows = shelves.stock_rows(catalog, moves)
    if as_json:
        return _json([{"sku": p.sku, "name": p.name, "onhand": n, "status": s}
                      for p, n, s in rows])
    return _lines("%s %d %s %s" % (p.sku, n, s, p.name) for p, n, s in rows)


def _cmd_low(catalog, moves, as_json):
    rows = shelves.low_rows(catalog, moves)
    if as_json:
        return _json([{"sku": p.sku, "onhand": n, "reorder": p.reorder, "buy": b}
                      for p, n, b in rows])
    return _lines("%s %d %d %d" % (p.sku, n, p.reorder, b) for p, n, b in rows)


def _cmd_history(catalog, moves, as_json, arg):
    sku = normalise_sku(arg)
    if sku is None or sku not in catalog:
        raise refuse("unknown SKU %r" % arg)
    rows = shelves.history_rows(sku, moves)
    if as_json:
        return _json([{"date": m.date.isoformat(), "delta": "%+d" % m.quantity,
                       "balance": b, "note": m.note} for m, b in rows])
    return _lines(
        "%s %+d %d%s" % (m.date.isoformat(), m.quantity, b, " " + m.note if m.note else "")
        for m, b in rows
    )


def _cmd_move(command, catalog, moves, existing, directory, args):
    date_text, sku_arg, qty_arg = args[:3]
    note = args[3].strip(" \t") if len(args) == 4 else ""
    if not _UINT.fullmatch(qty_arg) or int(qty_arg) < 1:
        raise refuse("quantity must be a whole number of one or more, got %r" % qty_arg)
    sku = normalise_sku(sku_arg)
    if sku is None or sku not in catalog:
        raise refuse("unknown SKU %r" % sku_arg)
    if "\n" in note or "\r" in note:
        raise refuse("a note may not contain a line break")
    try:
        note.encode("utf-8")
    except UnicodeEncodeError:
        raise refuse("note is not valid text")
    quantity = int(qty_arg) * (1 if command == "receive" else -1)
    new = Movement(parse_date(date_text), sku, quantity, note)
    _check_and_append(directory, moves, existing, [new])
    return shelves.format_movement(new) + "\n"


def _check_and_append(directory, moves, existing, new_moves):
    found = first_below_zero(list(moves) + new_moves)
    if found:
        move, total = found
        if move in new_moves and move.line == 0:
            raise refuse("stock of %s would go below zero (%d)" % (move.sku, total))
        raise refuse("%s.txt: line %d: stock of %s would go below zero (%d)"
                     % (MOVEMENTS, move.line, move.sku, total))
    _append(directory, existing, [shelves.format_movement(m) for m in new_moves])


def _find_order(orders, arg):
    order_id = normalise_order_id(arg)
    for order in orders:
        if order.id == order_id:
            return order
    raise refuse("unknown order %r" % arg)


def _cmd_fulfil(catalog, moves, orders, existing, directory, args):
    order = _find_order(orders, args[0])
    date = parse_date(args[1])
    if date < order.date:
        raise refuse("cannot ship %s on %s: before the order date %s"
                     % (order.id, date.isoformat(), order.date.isoformat()))
    report, new_moves = ordmod.plan_fulfil(order, moves, date)
    if new_moves:
        _check_and_append(directory, moves, existing, new_moves)
    shipped = ordmod.shipped_so_far(order, list(moves) + new_moves)
    rows = ["%s shipped %d backordered %d" % row for row in report]
    rows.append("status " + ordmod.order_status(order, shipped))
    return _lines(rows)


def _cmd_invoice(catalog, moves, orders, as_json, arg):
    order = _find_order(orders, arg)
    shipped = ordmod.shipped_so_far(order, moves)
    if not any(shipped.values()):
        raise refuse("nothing has shipped for %s" % order.id)
    quote = ordmod.price_order(ordmod.invoice_order(order, shipped), catalog)
    return _quote_output(quote, as_json, "invoice ")


def _cmd_report(catalog, moves, orders, fmt):
    rows = []
    for order in sorted(orders, key=lambda o: (o.date, int(o.id[3:]), o.id)):
        shipped = ordmod.shipped_so_far(order, moves)
        units = sum(shipped.values())
        quoted = ordmod.price_order(order, catalog).total
        invoiced = ordmod.money(0)
        if units:
            invoiced = ordmod.price_order(ordmod.invoice_order(order, shipped), catalog).total
        rows.append((order.id, order.date.isoformat(), order.customer,
                     ordmod.order_status(order, shipped),
                     sum(q for _, q in order.lines), units, str(quoted), str(invoiced)))
    if fmt == "json":
        keys = ("order", "date", "customer", "status", "ordered", "shipped",
                "quoted", "invoiced")
        return _json([dict(zip(keys, row)) for row in rows])
    if fmt == "csv":
        return _csv([("order", "date", "customer", "status", "ordered", "shipped",
                      "quoted", "invoiced")] + rows)
    return _lines("%s %s %s %s %d/%d %s %s" % (r[:4] + (r[5], r[4], r[6], r[7]))
                  for r in rows)


def run(argv):
    """Carry out one command line; return the stdout text or raise."""
    command, args, options = parse_args(argv)
    directory = options.get(DIR_OPT, ".")
    if not os.path.isdir(directory):
        raise Failure(2, "%s: not a directory" % directory)
    raw = {kind: _read(directory, kind) for kind in COMMANDS[command][2]}
    text = {kind: _decode(*raw[kind]) for kind in raw}
    catalog = _parse("catalog.txt", parse_catalog, text[CATALOG])
    moves = orders = None
    if MOVEMENTS in text:
        moves = _parse("movements.txt", parse_movements, text[MOVEMENTS], catalog)
    if ORDERS in text:
        orders = _parse("orders.txt", parse_orders, text[ORDERS], catalog)
    as_json = bool(options.get(JSON_OPT))
    existing = raw[MOVEMENTS][1] if MOVEMENTS in raw else b""
    if command == "stock":
        return _cmd_stock(catalog, moves, as_json)
    if command == "low":
        return _cmd_low(catalog, moves, as_json)
    if command == "history":
        return _cmd_history(catalog, moves, as_json, args[0])
    if command in ("receive", "ship"):
        return _cmd_move(command, catalog, moves, existing, directory, args)
    if command == "quote":
        order = _find_order(orders, args[0])
        return _quote_output(ordmod.price_order(order, catalog), as_json)
    if command == "fulfil":
        return _cmd_fulfil(catalog, moves, orders, existing, directory, args)
    if command == "invoice":
        return _cmd_invoice(catalog, moves, orders, as_json, args[0])
    return _cmd_report(catalog, moves, orders, options.get(FORMAT_OPT, "text"))


def _silence_stdout():
    """Point fd 1 at /dev/null so the exit-time flush cannot fail again."""
    try:
        fd = os.open(os.devnull, os.O_WRONLY)
        os.dup2(fd, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def _emit(text):
    try:
        sys.stdout.write(text)
        sys.stdout.flush()
    except BrokenPipeError:
        _silence_stdout()
    except OSError as exc:
        _silence_stdout()
        sys.stderr.write("stockroom: cannot write output: %s\n" % (exc.strerror or exc))
        return 2
    return 0


def _configure_streams():
    for stream, options in ((sys.stdout, {"encoding": "utf-8", "newline": "\n"}),
                            (sys.stderr, {"errors": "backslashreplace"})):
        reconfigure = getattr(stream, "reconfigure", None)
        if reconfigure is not None:
            try:
                reconfigure(**options)
            except (OSError, ValueError):
                pass


def main(argv=None):
    """Entry point: run the command line and return the exit status."""
    argv = sys.argv[1:] if argv is None else list(argv)
    _configure_streams()
    try:
        text = run(argv)
    except UsageError as exc:
        sys.stderr.write("stockroom: %s\n%s\n" % (exc, USAGE))
        return 2
    except Failure as exc:
        sys.stderr.write("stockroom: %s\n" % exc)
        return exc.code
    return _emit(text)

