"""Shared line reader, field validators, record types and the three parsers."""

import datetime
import re
import sys
from dataclasses import dataclass, field
from decimal import Decimal

# Python 3.11+ refuses to convert very long digit strings; a whole number in
# a data file may be any length, so lift that limit.
if hasattr(sys, "set_int_max_str_digits"):
    sys.set_int_max_str_digits(0)

WS = " \t"
TAX_BANDS = ("standard", "reduced", "zero")

SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
ORDER_ID_RE = re.compile(r"[Ss][Oo]-[0-9]+")
DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_PRICE_RE = re.compile(r"([0-9]+)(?:\.([0-9]{1,2}))?")
_UINT_RE = re.compile(r"[0-9]+")
_QTY_RE = re.compile(r"[+-]?[0-9]+")
_TOKEN_RE = re.compile(r"[^ \t]+")
_MOVE_RE = re.compile(
    r"[ \t]*([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.DOTALL
)
_LINE_RE = re.compile(r"([A-Za-z]{2,4}-[0-9]{3})\*([0-9]+)")


class ParseError(ValueError):
    """A mistake in a data file; ``line`` is the 1-based line number."""

    def __init__(self, message, line=None):
        self.line = line
        self.reason = message
        text = message if line is None else "line %d: %s" % (line, message)
        super().__init__(text)


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"


@dataclass(frozen=True)
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str = ""
    line: int = field(default=0, compare=False)


@dataclass(frozen=True)
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: list
    line: int = field(default=0, compare=False)


def normalise_sku(text):
    """Upper-case SKU if ``text`` is a well-formed SKU, else None."""
    return text.upper() if SKU_RE.fullmatch(text) else None


def normalise_order_id(text):
    """Upper-case order id if ``text`` is a well-formed one, else None."""
    return text.upper() if ORDER_ID_RE.fullmatch(text) else None


def parse_date(text):
    """A ``datetime.date`` for ``YYYY-MM-DD`` text, or None."""
    if not DATE_RE.fullmatch(text):
        return None
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:]))
    except ValueError:
        return None


def _content_lines(text):
    """Yield (line number, line) for every line that is not blank or comment."""
    if text.startswith("﻿"):
        text = text[1:]
    for number, raw in enumerate(text.split("\n"), 1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        stripped = raw.strip(WS)
        if not stripped or stripped.startswith("#"):
            continue
        yield number, raw


def _date(text, number):
    value = parse_date(text)
    if value is None:
        raise ParseError("invalid date %r (want YYYY-MM-DD)" % text, number)
    return value


def _sku(text, number, catalog=None):
    if not SKU_RE.fullmatch(text):
        raise ParseError("invalid SKU %r" % text, number)
    sku = text.upper()
    if catalog is not None and sku not in catalog:
        raise ParseError("unknown SKU %s (not in the catalogue)" % sku, number)
    return sku


def parse_catalog(text):
    """Parse ``catalog.txt`` text into a dict of SKU -> Product."""
    catalog = {}
    for number, raw in _content_lines(text):
        fields = [f.strip(WS) for f in raw.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(
                "expected 4 or 5 fields separated by '|', found %d" % len(fields),
                number,
            )
        sku = _sku(fields[0], number)
        if sku in catalog:
            raise ParseError("duplicate SKU %s" % sku, number)
        name = fields[1]
        if not name:
            raise ParseError("empty name", number)
        match = _PRICE_RE.fullmatch(fields[2])
        if not match:
            raise ParseError("invalid price %r" % fields[2], number)
        whole, frac = match.groups()
        price = Decimal("%s.%s" % (whole, (frac or "").ljust(2, "0")))
        if price < Decimal("0.01"):
            raise ParseError("price must be at least 0.01", number)
        if not _UINT_RE.fullmatch(fields[3]):
            raise ParseError("invalid reorder level %r" % fields[3], number)
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower() if fields[4].isascii() else fields[4]
            if tax not in TAX_BANDS:
                raise ParseError("invalid tax band %r" % fields[4], number)
        catalog[sku] = Product(sku, name, price, int(fields[3]), tax)
    return catalog


def sorted_movements(movements):
    """Movements in the order they count: by date, file order within a day."""
    return sorted(movements, key=lambda m: m.date)


def first_below_zero(movements):
    """(movement, balance) of the first movement taking a SKU below zero."""
    balance = {}
    for move in sorted_movements(movements):
        total = balance.get(move.sku, 0) + move.quantity
        balance[move.sku] = total
        if total < 0:
            return move, total
    return None


def parse_movements(text, catalog):
    """Parse ``movements.txt`` text into a list of Movement, in file order."""
    moves = []
    for number, raw in _content_lines(text):
        match = _MOVE_RE.fullmatch(raw)
        if not match:
            raise ParseError("expected DATE SKU QUANTITY [NOTE]", number)
        date_text, sku_text, qty_text, note = match.groups()
        date = _date(date_text, number)
        sku = _sku(sku_text, number, catalog)
        if not _QTY_RE.fullmatch(qty_text):
            raise ParseError("invalid quantity %r" % qty_text, number)
        quantity = int(qty_text)
        if quantity == 0:
            raise ParseError("quantity must not be zero", number)
        moves.append(Movement(date, sku, quantity, (note or "").strip(WS), number))
    found = first_below_zero(moves)
    if found:
        move, total = found
        raise ParseError(
            "stock of %s would go below zero (%d)" % (move.sku, total), move.line
        )
    return moves


def parse_orders(text, catalog):
    """Parse ``orders.txt`` text into a list of Order, in file order."""
    orders = []
    seen = set()
    for number, raw in _content_lines(text):
        tokens = _TOKEN_RE.findall(raw)
        if len(tokens) != 4:
            raise ParseError(
                "expected ORDER DATE CUSTOMER LINES, found %d fields" % len(tokens),
                number,
            )
        if not ORDER_ID_RE.fullmatch(tokens[0]):
            raise ParseError("invalid order number %r" % tokens[0], number)
        order_id = tokens[0].upper()
        if order_id in seen:
            raise ParseError("duplicate order %s" % order_id, number)
        seen.add(order_id)
        date = _date(tokens[1], number)
        lines = []
        used = set()
        for segment in tokens[3].split(","):
            match = _LINE_RE.fullmatch(segment)
            if not match:
                raise ParseError("invalid order line %r (want SKU*QTY)" % segment, number)
            sku = _sku(match.group(1), number, catalog)
            if sku in used:
                raise ParseError("duplicate SKU %s in order" % sku, number)
            used.add(sku)
            quantity = int(match.group(2))
            if quantity < 1:
                raise ParseError("quantity must be at least 1", number)
            lines.append((sku, quantity))
        orders.append(Order(order_id, date, tokens[2], lines, number))
    return orders
"""Stock levels, status, low-stock list and per-SKU history."""

from .parsing import sorted_movements


def stock_levels(catalog, movements):
    """Dict of SKU -> quantity on the shelf, for every catalogue product."""
    levels = {sku: 0 for sku in catalog}
    for move in movements:
        if move.sku in levels:
            levels[move.sku] += move.quantity
    return levels


def stock_status(onhand, reorder):
    """``out`` at zero, ``low`` at or under the reorder level, else ``ok``."""
    if onhand <= 0:
        return "out"
    return "low" if onhand <= reorder else "ok"


def buy_quantity(onhand, reorder):
    """How many to buy to get back to twice the reorder level (at least 1)."""
    return max(1, 2 * reorder - onhand)


def stock_rows(catalog, movements):
    """[(product, onhand, status)] by SKU."""
    levels = stock_levels(catalog, movements)
    return [
        (catalog[sku], levels[sku], stock_status(levels[sku], catalog[sku].reorder))
        for sku in sorted(catalog)
    ]


def low_rows(catalog, movements):
    """[(product, onhand, buy)] for every low or out product, by SKU."""
    rows = []
    for product, onhand, status in stock_rows(catalog, movements):
        if status != "ok":
            rows.append((product, onhand, buy_quantity(onhand, product.reorder)))
    return rows


def history_rows(sku, movements):
    """[(movement, balance)] for one SKU in the order the movements count."""
    rows = []
    balance = 0
    for move in sorted_movements(movements):
        if move.sku == sku:
            balance += move.quantity
            rows.append((move, balance))
    return rows


def format_movement(move):
    """``DATE SKU ±N[ NOTE]``."""
    text = "%s %s %+d" % (move.date.isoformat(), move.sku, move.quantity)
    return text + " " + move.note if move.note else text
"""Pricing, shipped-so-far, fulfil planning and order status."""

import dataclasses
import datetime
from dataclasses import dataclass
from decimal import Decimal
from fractions import Fraction

from .parsing import Movement, sorted_movements

TAX_RATES = {
    "standard": Fraction(20, 100),
    "reduced": Fraction(5, 100),
    "zero": Fraction(0),
}


@dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal
    taxable: Decimal
    tax: Decimal


@dataclass(frozen=True)
class Quote:
    order: str
    date: datetime.date
    customer: str
    lines: list
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


def _round_half_up(value):
    """Round a non-negative int or Fraction to an int, halves up."""
    value = Fraction(value)
    return (2 * value.numerator + value.denominator) // (2 * value.denominator)


def money(pennies):
    """A two-decimal Decimal for an integer number of pennies."""
    sign = "-" if pennies < 0 else ""
    pennies = abs(pennies)
    return Decimal("%s%d.%02d" % (sign, pennies // 100, pennies % 100))


def price_order(order, catalog):
    """Price a whole order (pricing steps 1-6) and return a Quote."""
    rows = []
    for sku, quantity in order.lines:
        unit = _round_half_up(Fraction(catalog[sku].price) * 100)
        gross = quantity * unit
        percent = 10 if quantity >= 50 else 5 if quantity >= 10 else 0
        discount = _round_half_up(Fraction(gross * percent, 100))
        rows.append((sku, quantity, unit, gross, discount, gross - discount))
    subtotal = sum(row[5] for row in rows)
    order_discount = _round_half_up(Fraction(subtotal * 3, 100)) if subtotal >= 50000 else 0

    shares = [0] * len(rows)
    if order_discount:
        remainders = []
        for index, row in enumerate(rows):
            shares[index], rest = divmod(order_discount * row[5], subtotal)
            remainders.append(rest)
        leftover = order_discount - sum(shares)
        by_remainder = sorted(range(len(rows)), key=lambda i: (-remainders[i], i))
        for index in by_remainder[:leftover]:
            shares[index] += 1

    lines = []
    total_tax = 0
    for row, share in zip(rows, shares):
        sku, quantity, unit, gross, discount, net = row
        taxable = net - share
        tax = _round_half_up(taxable * TAX_RATES[catalog[sku].tax])
        total_tax += tax
        lines.append(
            QuoteLine(sku, quantity, money(unit), money(gross), money(-discount),
                      money(net), money(taxable), money(tax))
        )
    return Quote(
        order.id, order.date, order.customer, lines, money(subtotal),
        money(-order_discount), money(total_tax),
        money(subtotal - order_discount + total_tax),
    )


def shipped_so_far(order, movements):
    """Dict of SKU -> units already shipped for ``order`` (capped at ordered)."""
    note = "order " + order.id
    shipped = {}
    for sku, quantity in order.lines:
        out = -sum(
            m.quantity for m in movements
            if m.sku == sku and m.quantity < 0 and m.note == note
        )
        shipped[sku] = min(quantity, out)
    return shipped


def order_status(order, shipped):
    """``complete``, ``open`` or ``partial`` given a shipped-so-far dict."""
    owed = sum(quantity - shipped[sku] for sku, quantity in order.lines)
    if owed == 0:
        return "complete"
    return "partial" if sum(shipped.values()) else "open"


def invoice_order(order, shipped):
    """The order restricted to the shipped quantities (zero lines dropped)."""
    lines = [(sku, shipped[sku]) for sku, _ in order.lines if shipped[sku] > 0]
    return dataclasses.replace(order, lines=lines)


def availability(movements, sku, date):
    """Most of ``sku`` that can leave on ``date`` without breaking a later movement."""
    on_date = 0
    later_low = None
    balance = 0
    for move in sorted_movements(movements):
        if move.sku != sku:
            continue
        balance += move.quantity
        if move.date <= date:
            on_date = balance
        elif later_low is None or balance < later_low:
            later_low = balance
    best = on_date if later_low is None else min(on_date, later_low)
    return max(0, best)


def plan_fulfil(order, movements, date):
    """([(sku, shipped_now, backordered)], [new Movement]) for a fulfil run."""
    shipped = shipped_so_far(order, movements)
    report = []
    new_moves = []
    for sku, quantity in order.lines:
        owed = quantity - shipped[sku]
        ship = min(owed, availability(movements, sku, date))
        report.append((sku, ship, owed - ship))
        if ship > 0:
            new_moves.append(Movement(date, sku, -ship, "order " + order.id))
    return report, new_moves
